create table public.flight_rule_evaluations(id uuid primary key default gen_random_uuid(),schedule_import_id uuid not null references public.flight_schedule_imports(id) on delete cascade,rule_key text not null,rule_version integer not null default 1,rules_engine_version text not null default 'flight-rules-engine/1.0.0',ruleset_version text not null default 'gol-operational-ruleset/2026.1',schedule_state text not null check(schedule_state in('PLANNED','EXECUTION_SNAPSHOT','FINAL_EXECUTED')),subject_type text not null,subject_id uuid,evaluation_status text not null check(evaluation_status in('PASS','FAIL','UNKNOWN','NOT_APPLICABLE')),evaluation_context text not null default 'NORMAL',severity text not null check(severity in('INFO','LOW','MEDIUM','HIGH','CRITICAL')),confidence text not null check(confidence in('HIGH','MEDIUM','LOW')),facts_snapshot jsonb not null default '{}'::jsonb,explanation text not null,source_references jsonb not null default '[]'::jsonb,evaluated_at timestamptz not null default now(),unique(schedule_import_id,rule_key,rule_version,subject_type,subject_id));
create index flight_rule_evaluations_import_rule_status_idx on public.flight_rule_evaluations(schedule_import_id,rule_key,evaluation_status);
alter table public.flight_rule_evaluations enable row level security;
create policy flight_rule_evaluations_owner_read on public.flight_rule_evaluations for select to authenticated using(exists(select 1 from public.flight_schedule_imports i where i.id=schedule_import_id and i.user_id=auth.uid()));
grant select on public.flight_rule_evaluations to authenticated;
grant select,insert,delete on public.flight_rule_evaluations to service_role;
